mapper.select:
SELECT sys_interface_log.* FROM sys_interface_log
WHERE create_time >= #{date}
AND `status` = 3
AND pact_id NOT IN (
    SELECT DISTINCT pact_id FROM sys_interface_log WHERE create_time >= #{date}
    AND `status` = 2
)
ORDER BY sys_interface_log.create_time DESC
LIMIT #{offset}, #{size}
